import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"UI Tour","description":"A visual tour of the Muxit web interface — panels, sidebars, editors, and where to find everything.","frontmatter":{"title":"UI Tour","description":"A visual tour of the Muxit web interface — panels, sidebars, editors, and where to find everything."},"headers":[],"relativePath":"getting-started/ui-tour.md","filePath":"getting-started/ui-tour.md"}'),r={name:"getting-started/ui-tour.md"};function n(i,t,l,d,c,h){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="ui-tour" tabindex="-1">UI Tour <a class="header-anchor" href="#ui-tour" aria-label="Permalink to &quot;UI Tour&quot;">​</a></h1><p>Muxit&#39;s web interface looks like a code editor (similar to VS Code), but it&#39;s designed for hardware control. Here&#39;s what each part does.</p><h2 id="layout-overview" tabindex="-1">Layout Overview <a class="header-anchor" href="#layout-overview" aria-label="Permalink to &quot;Layout Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                      Title Bar                           │</span></span>
<span class="line"><span>├───┬──────────┬───────────────────────┬───────────────────┤</span></span>
<span class="line"><span>│   │          │                       │                   │</span></span>
<span class="line"><span>│ A │  Left    │     Editor Area       │    Right          │</span></span>
<span class="line"><span>│ c │  Sidebar │   (scripts, configs,  │    Sidebar        │</span></span>
<span class="line"><span>│ t │          │    dashboards)        │   (AI Chat)       │</span></span>
<span class="line"><span>│ i │ Explorer │                       │                   │</span></span>
<span class="line"><span>│ v │   or     │                       │                   │</span></span>
<span class="line"><span>│ i │ Hardware │                       │                   │</span></span>
<span class="line"><span>│ t │          │                       │                   │</span></span>
<span class="line"><span>│ y │          ├───────────────────────┤                   │</span></span>
<span class="line"><span>│   │          │    Bottom Panel       │                   │</span></span>
<span class="line"><span>│ B │          │   (Logs / Output)     │                   │</span></span>
<span class="line"><span>│ a │          │                       │                   │</span></span>
<span class="line"><span>│ r │          │                       │                   │</span></span>
<span class="line"><span>├───┴──────────┴───────────────────────┴───────────────────┤</span></span>
<span class="line"><span>│                      Status Bar                          │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="activity-bar-left-edge" tabindex="-1">Activity Bar (Left Edge) <a class="header-anchor" href="#activity-bar-left-edge" aria-label="Permalink to &quot;Activity Bar (Left Edge)&quot;">​</a></h2><p>The vertical strip of icons on the far left. Click an icon to open its corresponding sidebar panel.</p><table tabindex="0"><thead><tr><th>Icon</th><th>Panel</th><th>What It Does</th></tr></thead><tbody><tr><td><strong>Files</strong></td><td>Explorer</td><td>Browse and manage your workspace files</td></tr><tr><td><strong>Plug</strong></td><td>Hardware</td><td>View connected devices and their live state</td></tr><tr><td><strong>Chat</strong></td><td>AI Chat</td><td>Natural language control, agents, and memory</td></tr><tr><td><strong>Gear</strong> (bottom)</td><td>Settings</td><td>Configure AI, voice, remote access, licensing</td></tr></tbody></table><p>You can drag icons to reorder them.</p><hr><h2 id="explorer-sidebar" tabindex="-1">Explorer Sidebar <a class="header-anchor" href="#explorer-sidebar" aria-label="Permalink to &quot;Explorer Sidebar&quot;">​</a></h2><p>The Explorer is your file manager for the workspace. It shows all your scripts, connectors, dashboards, and agents organized by type.</p><h3 id="file-tree" tabindex="-1">File Tree <a class="header-anchor" href="#file-tree" aria-label="Permalink to &quot;File Tree&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WORKSPACE</span></span>
<span class="line"><span>├── connectors/       ← Device configurations (.js)</span></span>
<span class="line"><span>│   ├── test-device.js</span></span>
<span class="line"><span>│   ├── webcam.js</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── scripts/          ← Automation scripts (.js)</span></span>
<span class="line"><span>│   ├── hello.js</span></span>
<span class="line"><span>│   ├── webcam-snapshot.js</span></span>
<span class="line"><span>│   ├── examples/</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── dashboards/       ← Dashboard layouts (.dashboard.json)</span></span>
<span class="line"><span>│   ├── demo.dashboard.json</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── agents/           ← Agent configs (.agent.json)</span></span>
<span class="line"><span>│   └── temperature-monitor.agent.json</span></span>
<span class="line"><span>├── drivers/          ← Custom drivers (.driver.js)</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>└── config/           ← Server configuration</span></span>
<span class="line"><span>    └── server.json</span></span></code></pre></div><h3 id="toolbar-actions" tabindex="-1">Toolbar Actions <a class="header-anchor" href="#toolbar-actions" aria-label="Permalink to &quot;Toolbar Actions&quot;">​</a></h3><ul><li><strong>New Script</strong> — Create a new <code>.js</code> file in <code>scripts/</code></li><li><strong>New Dashboard</strong> — Create a new <code>.dashboard.json</code> file in <code>dashboards/</code></li><li><strong>Refresh</strong> — Reload the file list from disk</li></ul><h3 id="special-sections" tabindex="-1">Special Sections <a class="header-anchor" href="#special-sections" aria-label="Permalink to &quot;Special Sections&quot;">​</a></h3><ul><li><strong>FAVORITES</strong> — Files you&#39;ve starred appear here for quick access</li><li><strong>RUNNING</strong> — Currently executing scripts appear here with a stop button</li></ul><h3 id="inline-actions" tabindex="-1">Inline Actions <a class="header-anchor" href="#inline-actions" aria-label="Permalink to &quot;Inline Actions&quot;">​</a></h3><p>Each file in the Explorer shows context-appropriate actions:</p><ul><li><strong>Scripts:</strong> Play/Stop buttons to run or stop the script</li><li><strong>Dashboards:</strong> Show button to open the live dashboard view</li><li><strong>All files:</strong> Star button to add to favorites</li></ul><hr><h2 id="hardware-panel" tabindex="-1">Hardware Panel <a class="header-anchor" href="#hardware-panel" aria-label="Permalink to &quot;Hardware Panel&quot;">​</a></h2><p>Click the plug icon in the Activity Bar to open the Hardware panel. This is your device control center.</p><h3 id="what-you-see" tabindex="-1">What You See <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What You See&quot;">​</a></h3><p>For each enabled connector:</p><ul><li><strong>Name</strong> and <strong>driver</strong> type</li><li><strong>Live property values</strong> — updated automatically via polling</li><li><strong>Actions</strong> — buttons to execute device actions</li><li><strong>Streams</strong> — available data streams (video, sensor data)</li></ul><h3 id="managing-connectors" tabindex="-1">Managing Connectors <a class="header-anchor" href="#managing-connectors" aria-label="Permalink to &quot;Managing Connectors&quot;">​</a></h3><ul><li><strong>Enable/Disable</strong> — Check or uncheck connectors (within your license tier limit)</li><li><strong>Add Connector</strong> — Click the &quot;+&quot; button to create a new connector from a driver template</li><li><strong>Reload</strong> — Reload all connector configs from disk (useful after editing files)</li></ul><h3 id="state-indicators" tabindex="-1">State Indicators <a class="header-anchor" href="#state-indicators" aria-label="Permalink to &quot;State Indicators&quot;">​</a></h3><p>Properties with polling enabled show live values that update automatically. Values change in real-time as the hardware state changes (or as the TestDevice simulates changes).</p><hr><h2 id="editor-area" tabindex="-1">Editor Area <a class="header-anchor" href="#editor-area" aria-label="Permalink to &quot;Editor Area&quot;">​</a></h2><p>The center of the screen is the editor, where you write scripts, edit connector configs, and view dashboards.</p><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><p>Each open file gets a tab. You can:</p><ul><li><strong>Click</strong> a tab to switch to it</li><li><strong>Drag</strong> tabs to reorder them</li><li><strong>Close</strong> tabs with the X button</li><li><strong>Split</strong> the editor into multiple groups (side-by-side editing)</li></ul><h3 id="script-editing" tabindex="-1">Script Editing <a class="header-anchor" href="#script-editing" aria-label="Permalink to &quot;Script Editing&quot;">​</a></h3><p>When editing a <code>.js</code> script file:</p><ul><li><strong>Run</strong> button in the toolbar — execute the script</li><li><strong>Stop</strong> button — stop a running script</li><li><strong>Autocomplete</strong> — type <code>connector(</code> to see device names, <code>dev.</code> to see properties and actions, <code>log.</code> for logging methods</li></ul><h3 id="dashboard-editing" tabindex="-1">Dashboard Editing <a class="header-anchor" href="#dashboard-editing" aria-label="Permalink to &quot;Dashboard Editing&quot;">​</a></h3><p>When you open a <code>.dashboard.json</code> file, you see the live dashboard with widgets. Toggle <strong>edit mode</strong> to:</p><ul><li><strong>Add widgets</strong> from the widget palette</li><li><strong>Drag</strong> widgets to reposition them on the grid</li><li><strong>Resize</strong> widgets by dragging the corner handle</li><li><strong>Configure</strong> widgets by clicking them (set bindings, labels, colors, ranges)</li><li><strong>Delete</strong> widgets with the Delete key or remove button</li></ul><p>Changes are saved automatically to the JSON file.</p><h3 id="csv-charts" tabindex="-1">CSV Charts <a class="header-anchor" href="#csv-charts" aria-label="Permalink to &quot;CSV Charts&quot;">​</a></h3><p>Opening a <code>.csv</code> or <code>.tsv</code> file (for example, one written by a measurement script via <code>connector(&#39;files&#39;).openText(&#39;runs/log.csv&#39;).append([...])</code>) renders it as an interactive line chart. Use the control strip above the chart to:</p><ul><li><strong>Chart / Text toggle</strong> — switch between the chart and the raw Monaco text view. The text view keeps the usual undo/redo/save controls so small edits are still possible.</li><li><strong>X-axis dropdown</strong> — pick any column as the X-axis, or fall back to the row index. Timestamp columns are auto-detected and switch the X-axis to a time scale.</li><li><strong>Series checkboxes</strong> — toggle which numeric columns are plotted.</li></ul><p>The parser auto-detects the delimiter (<code>,</code>, <code>;</code>, or tab) and whether the first row is a header. Files larger than 100 000 rows are rendered with only the first 100 000 for responsiveness (a banner shows the full row count).</p><hr><h2 id="bottom-panel-output-logs" tabindex="-1">Bottom Panel (Output / Logs) <a class="header-anchor" href="#bottom-panel-output-logs" aria-label="Permalink to &quot;Bottom Panel (Output / Logs)&quot;">​</a></h2><p>Toggle with <code>Ctrl+J</code>. Shows two types of output:</p><h3 id="script-output" tabindex="-1">Script Output <a class="header-anchor" href="#script-output" aria-label="Permalink to &quot;Script Output&quot;">​</a></h3><p>When a script runs, its <code>log.info()</code>, <code>log.warn()</code>, <code>log.error()</code>, and <code>log.debug()</code> messages appear here with timestamps. Each script&#39;s output is labeled with its name.</p><h3 id="server-logs" tabindex="-1">Server Logs <a class="header-anchor" href="#server-logs" aria-label="Permalink to &quot;Server Logs&quot;">​</a></h3><p>System-level messages from the Muxit server — driver initialization, connection events, errors. Useful for diagnosing issues.</p><p>You can clear logs with the trash icon.</p><hr><h2 id="ai-chat-sidebar" tabindex="-1">AI Chat Sidebar <a class="header-anchor" href="#ai-chat-sidebar" aria-label="Permalink to &quot;AI Chat Sidebar&quot;">​</a></h2><p>Click the chat icon in the Activity Bar to open the right sidebar. It has multiple tabs:</p><h3 id="chat-tab" tabindex="-1">Chat Tab <a class="header-anchor" href="#chat-tab" aria-label="Permalink to &quot;Chat Tab&quot;">​</a></h3><p>Type natural language commands to control your devices:</p><ul><li><em>&quot;Set the voltage to 12V&quot;</em></li><li><em>&quot;Read the temperature&quot;</em></li><li><em>&quot;Write a script that monitors current&quot;</em></li></ul><p>The AI calls device tools to fulfill your request. In <strong>confirm</strong> mode, you approve each tool call before it executes.</p><h3 id="agents-tab" tabindex="-1">Agents Tab <a class="header-anchor" href="#agents-tab" aria-label="Permalink to &quot;Agents Tab&quot;">​</a></h3><p>View and manage autonomous AI agents. Start agents from saved configs or create them on the fly. Monitor their plan-act-observe loop in real-time.</p><h3 id="memory-tab" tabindex="-1">Memory Tab <a class="header-anchor" href="#memory-tab" aria-label="Permalink to &quot;Memory Tab&quot;">​</a></h3><p>View facts the AI has remembered across sessions. Categories: preferences, device info, procedures, notes. You can edit or delete memories manually.</p><h3 id="voice-controls" tabindex="-1">Voice Controls <a class="header-anchor" href="#voice-controls" aria-label="Permalink to &quot;Voice Controls&quot;">​</a></h3><p>In the chat header:</p><ul><li><strong>Mic button</strong> — Push to talk, or toggle hands-free listening</li><li><strong>Speaker icon</strong> — Toggle text-to-speech for AI responses</li><li><strong>Mic dropdown</strong> — Voice settings (wake word, sensitivity)</li></ul><p>In the chat itself:</p><ul><li><strong>Live &quot;You&quot; bubble</strong> — Your in-progress voice transcription, shown at the bottom of the chat while the mic is open</li><li><strong>Speaking… [Stop]</strong> — Appears under the latest AI reply while TTS is playing; click Stop to interrupt long replies</li></ul><hr><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Click the gear icon at the bottom of the Activity Bar to open the Settings panel.</p><table tabindex="0"><thead><tr><th>Section</th><th>What You Configure</th></tr></thead><tbody><tr><td><strong>AI Services</strong></td><td>Model selection, safety mode, model favorites</td></tr><tr><td><strong>AI Instructions</strong></td><td>Custom system prompt for the AI assistant</td></tr><tr><td><strong>Voice</strong></td><td>Speech-to-text, text-to-speech, wake word</td></tr><tr><td><strong>Remote Access</strong></td><td>Password, HTTPS, bind address</td></tr><tr><td><strong>License</strong></td><td>Activation, tier info, trial status</td></tr></tbody></table><p>Settings are saved to <code>workspace/config/server.json</code>.</p><hr><h2 id="status-bar" tabindex="-1">Status Bar <a class="header-anchor" href="#status-bar" aria-label="Permalink to &quot;Status Bar&quot;">​</a></h2><p>The thin bar at the bottom of the screen shows:</p><ul><li><strong>Connection status</strong> — Whether the WebSocket connection to the server is active</li><li><strong>Running scripts</strong> — Count of currently executing scripts</li></ul><hr><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+B</code></td><td>Toggle left sidebar</td></tr><tr><td><code>Ctrl+Shift+B</code></td><td>Toggle right sidebar</td></tr><tr><td><code>Ctrl+J</code></td><td>Toggle bottom panel</td></tr><tr><td><code>Ctrl+,</code></td><td>Open settings</td></tr><tr><td><code>Ctrl+S</code></td><td>Save current file</td></tr><tr><td><code>Ctrl+N</code></td><td>New file</td></tr></tbody></table><p>See the full <a href="/guides/keyboard-shortcuts.html">Keyboard Shortcuts</a> reference for editor shortcuts.</p><hr><h2 id="drag-and-drop" tabindex="-1">Drag-and-Drop <a class="header-anchor" href="#drag-and-drop" aria-label="Permalink to &quot;Drag-and-Drop&quot;">​</a></h2><p>Muxit supports cross-panel drag-and-drop for quick setup. The Hardware panel itself shows a &quot;Tip:&quot; banner when you expand a connector, reminding you that everything below it is draggable.</p><table tabindex="0"><thead><tr><th>Drag From</th><th>Drop On</th><th>Result</th></tr></thead><tbody><tr><td>Hardware <strong>property</strong></td><td>Script editor</td><td>Inserts <code>connector(&quot;name&quot;).prop</code></td></tr><tr><td>Hardware <strong>action</strong></td><td>Script editor</td><td>Inserts <code>connector(&quot;name&quot;).doThing(arg1, arg2)</code></td></tr><tr><td>Hardware <strong>stream</strong></td><td>Script editor</td><td>Inserts <code>stream(&quot;name&quot;, &quot;streamName&quot;, data)</code></td></tr><tr><td>Hardware property</td><td>Dashboard widget</td><td>Sets the widget&#39;s data binding</td></tr><tr><td>Hardware stream</td><td>Dashboard widget</td><td>Sets the stream binding</td></tr><tr><td>Script (from Explorer)</td><td>Dashboard grid</td><td>Creates a script-control widget</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Now that you know the interface:</p><ul><li><a href="/examples/first-script.html">Your First Script</a> — Write and run your first automation script</li><li><a href="/examples/first-dashboard.html">Your First Dashboard</a> — Build a live dashboard with widgets</li><li><a href="/examples/first-connector.html">Your First Connector</a> — Create a device connector configuration</li></ul>`,93)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
